import { createClient } from '@supabase/supabase-js';
import './style.css';
const url=import.meta.env.VITE_SUPABASE_URL,key=import.meta.env.VITE_SUPABASE_ANON_KEY;
const db=url&&key?createClient(url,key):null;
const app=document.querySelector('#app');
const state={session:null,profile:null,projects:[],project:null,observations:[],lang:localStorage.getItem('ge_lang')||'en',page:'home',detail:null,history:[]};
const tr=(en,es)=>state.lang==='es'?es:en;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v?new Intl.DateTimeFormat(state.lang==='es'?'es-US':'en-US',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'';
const localDateKey=(v=new Date())=>{const d=new Date(v),y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`};
const deviceZone=()=>Intl.DateTimeFormat().resolvedOptions().timeZone||'Local';
const error=e=>{document.querySelector('#message').textContent=e?.message||String(e)};
let restoringHistory=false;
function navigate(page,detail=null,{replace=false}={}){state.page=page;state.detail=detail;const entry={geSafety:true,page,detail};if(!restoringHistory){if(replace)history.replaceState(entry,'',location.href);else history.pushState(entry,'',location.href)}render()}
function back(){if(history.state?.geSafety&&state.page!=='home')history.back();else navigate('home',null,{replace:true})}
function frame(body){app.innerHTML=`<header><div class="brand"><img src="/ge-logo.png" alt="G&E Florida Contractors"><span>G&E <small>SAFETY DEPARTMENT</small></span></div><nav>${state.session&&state.page!=='home'?'<button id="global-back" class="home-nav" aria-label="'+tr('Back','Atrás')+'">← <span>'+tr('Back','Atrás')+'</span></button><button id="global-home" class="home-nav" aria-label="'+tr('Home','Inicio')+'">⌂ <span>'+tr('Home','Inicio')+'</span></button>':''}${state.session?'<button id="notification-menu" class="notification-menu" aria-label="'+tr('Notifications','Notificaciones')+'">🔔<span id="notification-count"></span></button>':''}<button id="language">${state.lang==='es'?'EN':'ES'}</button>${state.session?'<button id="password-menu">'+tr('Settings','Configuración')+'</button><button id="logout">'+tr('Sign out','Salir')+'</button>':''}</nav></header><div id="message" role="alert"></div><main>${body}</main>${state.session&&state.page!=='home'?'<div class="device-back-bar"><button id="mobile-global-back" class="mobile-nav-button mobile-back-button" aria-label="'+tr('Back','Atrás')+'"><span>←</span><small>'+tr('Back','Atrás')+'</small></button><button id="mobile-global-home" class="mobile-nav-button mobile-home-button" aria-label="'+tr('Home','Inicio')+'"><span>⌂</span><small>'+tr('Home','Inicio')+'</small></button></div>':''}`;const mb=document.querySelector('#mobile-global-back'),mh=document.querySelector('#mobile-global-home');if(mb)mb.onclick=back;if(mh)mh.onclick=()=>navigate('home');document.querySelector('#language').onclick=()=>{state.lang=state.lang==='es'?'en':'es';localStorage.setItem('ge_lang',state.lang);render()};if(state.session){const nm=document.querySelector('#notification-menu');if(nm){nm.onclick=()=>navigate('notifications');db.from('notifications').select('id',{count:'exact',head:true}).is('read_at',null).then(({count})=>{const el=document.querySelector('#notification-count');if(el&&count){el.textContent=count>99?'99+':String(count);el.classList.add('show')}})}const b=document.querySelector('#global-back');if(b)b.onclick=back;const h=document.querySelector('#global-home');if(h)h.onclick=()=>navigate('home');document.querySelector('#logout').onclick=()=>db.auth.signOut();document.querySelector('#password-menu').onclick=()=>navigate('setPassword')}}
function render(){if(!db)return frame(`<section class="card"><h1>${tr('Setup required','Configuración necesaria')}</h1><p>${tr('Create a Supabase project and copy .env.example to .env with its URL and publishable key.','Cree un proyecto de Supabase y copie .env.example a .env con la URL y clave pública.')}</p></section>`);if(!state.session)return login();if(state.page==='setPassword')return setPassword();if(!state.profile)return frame(`<section class="card"><h1>${tr('Access pending','Acceso pendiente')}</h1><p>${tr('An administrator must add your company email as a team member.','Un administrador debe agregar su correo de la compañía al equipo.')}</p></section>`);if(!state.projects.length&&state.profile.role!=='admin')return frame(`<section class="card"><h1>${tr('Waiting for project access','Esperando acceso al proyecto')}</h1><p>${tr('An administrator must assign you to a project.','Un administrador debe asignarte a un proyecto.')}</p></section>`);if(state.page==='notifications')return notificationsPage();if(state.page==='admin')return admin();if(state.page==='observations')return observationsList();if(state.page==='corrections')return correctionsList();if(state.page==='discipline')return discipline();if(state.page==='disciplineReport')return disciplineReport();if(state.page==='safetyWalk')return safetyWalk();if(state.page==='safetyWalkReport')return safetyWalkReport();if(state.page==='observationReport')return observationReport();if(state.page==='detail')return detail();if(state.page==='new')return newObservation();if(state.page==='reportCenter')return reportCenter();if(state.page==='report')return report();home()}
async function notificationsPage(){const q=await db.from('notifications').select('id,project_id,observation_id,type,title,message,priority,read_at,created_at').order('created_at',{ascending:false}).limit(100);if(q.error)return error(q.error);const rows=q.data||[],unread=rows.filter(x=>!x.read_at).length;frame(`<section class="notifications-shell"><div class="section-heading"><div><h1>🔔 ${tr('Notifications','Notificaciones')}</h1><p>${tr('Safety actions requiring your attention and follow-up.','Acciones de Safety que requieren su atención y seguimiento.')}</p></div>${unread?`<button class="secondary" id="mark-all">${tr('Mark all read','Marcar todas leídas')}</button>`:''}</div><div class="notification-summary"><strong>${unread}</strong><span>${tr('Unread','Sin leer')}</span></div><div class="notification-list">${rows.length?rows.map(n=>`<button class="notification-card ${n.read_at?'read':'unread'} ${esc(n.priority)}" data-id="${n.id}" data-observation="${n.observation_id||''}"><div class="notification-icon">${n.type==='observation_reminder'?'⏱':'⚠'}</div><div><div class="notification-card-head"><strong>${esc(n.title)}</strong><time>${esc(fmt(n.created_at))}</time></div><p>${esc(n.message)}</p><small>${n.type==='observation_reminder'?tr('30-minute follow-up reminder','Recordatorio de seguimiento de 30 minutos'):tr('New assigned activity','Nueva actividad asignada')}</small></div></button>`).join(''):`<div class="empty-state"><strong>${tr('No notifications','No hay notificaciones')}</strong><p>${tr('You are up to date.','Está al día.')}</p></div>`}</div></section>`);document.querySelectorAll('.notification-card').forEach(el=>el.onclick=async()=>{await db.from('notifications').update({read_at:new Date().toISOString()}).eq('id',el.dataset.id);if(el.dataset.observation)navigate('detail',el.dataset.observation);else render()});const all=document.querySelector('#mark-all');if(all)all.onclick=async()=>{const r=await db.from('notifications').update({read_at:new Date().toISOString()}).is('read_at',null);if(r.error)return error(r.error);render()}}

function login(mode='signIn'){const signup=mode==='signUp';frame(`<section class="card narrow"><h1>${signup?tr('Create your account','Crear tu cuenta'):tr('Sign in','Iniciar sesión')}</h1><form id="login">${signup?`<label>${tr('Full name','Nombre completo')}<input name="name" required autocomplete="name"></label>`:''}<label>${tr('Company email','Correo de la compañía')}<input type="email" name="email" required autocomplete="email"></label><label>${tr('Password','Contraseña')}<input type="password" name="password" required minlength="8" autocomplete="${signup?'new-password':'current-password'}"></label><button>${signup?tr('Create account','Crear cuenta'):tr('Sign in','Entrar')}</button></form>${!signup?`<p><button class="secondary" id="forgot">${tr('Forgot password?','¿Olvidaste tu contraseña?')}</button></p>`:''}<p><button class="secondary" id="mode">${signup?tr('Already have an account? Sign in','¿Ya tienes cuenta? Entrar'):tr('Create an account','Crear cuenta')}</button></p></section>`);document.querySelector('#mode').onclick=()=>login(signup?'signIn':'signUp');if(!signup)document.querySelector('#forgot').onclick=()=>forgotPassword();document.querySelector('#login').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const email=String(f.get('email')).trim();const password=String(f.get('password'));if(signup&&!email.toLowerCase().endsWith('@geflcontractors.com'))return error(tr('Use your @geflcontractors.com company email','Usa tu correo de compañía @geflcontractors.com'));const result=signup?await db.auth.signUp({email,password,options:{data:{name:String(f.get('name')).trim()}}}):await db.auth.signInWithPassword({email,password});if(result.error)return error(result.error);if(signup&&!result.data.session){frame(`<section class="card narrow"><h1>${tr('Check your email','Revisa tu correo')}</h1><p>${tr('Confirm your email, then return to sign in.','Confirma tu correo y vuelve a iniciar sesión.')}</p><button id="back-login">${tr('Sign in','Entrar')}</button></section>`);document.querySelector('#back-login').onclick=()=>login()}}}
function forgotPassword(){frame(`<section class="card narrow"><h1>${tr('Reset password','Restablecer contraseña')}</h1><form id="reset"><label>${tr('Company email','Correo de la compañía')}<input type="email" name="email" required></label><button>${tr('Send recovery link','Enviar enlace')}</button></form><p><button class="secondary" id="back-login">${tr('Back to sign in','Volver a entrar')}</button></p></section>`);document.querySelector('#back-login').onclick=()=>login();document.querySelector('#reset').onsubmit=async e=>{e.preventDefault();const email=String(new FormData(e.target).get('email')).trim();const {error:err}=await db.auth.resetPasswordForEmail(email,{redirectTo:window.location.origin});if(err)return error(err);frame(`<section class="card narrow"><h1>${tr('Check your email','Revisa tu correo')}</h1><p>${tr('If this account exists, a recovery link was sent.','Si la cuenta existe, se envió un enlace de recuperación.')}</p></section>`)}}
function setPassword(){frame(`<section class="card narrow"><h1>${tr('Set your password','Crea tu contraseña')}</h1><form id="password-form"><label>${tr('New password','Nueva contraseña')}<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><label>${tr('Confirm password','Confirmar contraseña')}<input type="password" name="confirmation" required minlength="8" autocomplete="new-password"></label><button>${tr('Save password','Guardar contraseña')}</button></form></section>`);document.querySelector('#password-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),p=String(f.get('password'));if(p!==f.get('confirmation'))return error(tr('Passwords do not match','Las contraseñas no coinciden'));const {error:err}=await db.auth.updateUser({password:p});if(err)return error(err);state.page='home';await refresh()}}
async function refresh(){const {data:{session}}=await db.auth.getSession();state.session=session;await load();render()}
async function load(){if(!state.session){state.profile=null;return}const p=await db.from('profiles').select('*').eq('id',state.session.user.id).maybeSingle();if(p.error)return error(p.error);state.profile=p.data;if(!p.data)return;const [projects,obs]=await Promise.all([db.from('projects').select('*').order('name'),db.from('observations').select('*, creator:profiles!observations_created_by_fkey(name), assignee:profiles!observations_assigned_to_fkey(name), foreman:profiles!observations_foreman_id_fkey(name), jobsite_safety:profiles!observations_jobsite_safety_id_fkey(name)').order('created_at',{ascending:false})]);if(projects.error||obs.error)return error(projects.error||obs.error);state.projects=projects.data;state.observations=obs.data;if(!state.projects.some(x=>x.id===state.project))state.project=state.projects[0]?.id||null}
function nav(){return `<div class="toolbar"><select id="project">${state.projects.map(p=>`<option value="${p.id}" ${p.id===state.project?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button id="report">${tr('Daily report','Reporte diario')}</button><button id="new">+ ${tr('Observation','Observación')}</button>${state.profile.role==='admin'?`<button id="admin">${tr('Projects & team','Proyectos y equipo')}</button>`:''}</div>`}
function bindNav(){document.querySelector('#project').onchange=e=>{state.project=e.target.value;render()};document.querySelector('#report').onclick=()=>navigate('report');document.querySelector('#new').onclick=()=>navigate('new');const a=document.querySelector('#admin');if(a)a.onclick=()=>navigate('admin')}
async function home(){const rows=state.observations.filter(o=>o.project_id===state.project),open=rows.filter(o=>o.status==='open').length,pending=rows.filter(o=>o.status==='pending_verification').length,closed=rows.filter(o=>o.status==='closed').length,highOpen=rows.filter(o=>o.priority==='high'&&o.status!=='closed').length,myOpen=rows.filter(o=>o.assigned_to===state.profile.id&&o.status!=='closed').length,todayKey=localDateKey(new Date()),walkCheck=await db.from('daily_safety_walks').select('id,overall_status,created_at').eq('project_id',state.project).order('created_at',{ascending:false}).limit(20),todayWalk=(walkCheck.data||[]).find(x=>localDateKey(x.created_at)===todayKey),name=state.profile?.name?.split(' ')[0]||tr('Team','Equipo'),hour=new Date().getHours(),greeting=hour<12?tr('Good morning','Buenos días'):hour<18?tr('Good afternoon','Buenas tardes'):tr('Good evening','Buenas noches'),initials=(state.profile?.name||'GE').split(/\\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase(),today=new Intl.DateTimeFormat(state.lang==='es'?'es-US':'en-US',{dateStyle:'long'}).format(new Date());frame(`<section class="home-shell"><div class="home-welcome"><div><h1>${greeting}, ${esc(name)}</h1><p>${tr('Safety Today. A Safer Tomorrow.','Seguridad hoy. Un mañana más seguro.')}</p></div><div class="user-avatar">${esc(initials)}</div></div><div class="project-label">${tr('Project','Proyecto')}</div><select class="project-picker" id="home-project">${state.projects.map(p=>`<option value="${p.id}" ${p.id===state.project?'selected':''}>${esc(p.name)}</option>`).join('')}</select><div class="today-line"><span>${tr('Today','Hoy')}</span><span>${esc(today)}</span></div><section class="command-center"><div class="command-head"><div><small>${tr("SAFETY COMMAND CENTER","CENTRO DE CONTROL SAFETY")}</small><h2>${tr("Today’s Priorities","Prioridades de Hoy")}</h2></div><span>${esc(today)}</span></div><div class="command-grid"><button class="command-alert high" id="cmd-high"><strong>${highOpen}</strong><span>${tr("High Priority Open","Prioridad Alta Abierta")}</span><small>${tr("Requires attention","Requiere atención")}</small></button><button class="command-alert mine" id="cmd-mine"><strong>${myOpen}</strong><span>${tr("My Open Tasks","Mis Tareas Abiertas")}</span><small>${tr("Assigned directly to you","Asignadas directamente a usted")}</small></button><button class="command-alert review" id="cmd-review"><strong>${pending}</strong><span>${tr("Waiting Safety Review","Esperando Revisión Safety")}</span><small>${tr("Corrections to verify","Correcciones por verificar")}</small></button><button class="command-alert walk ${todayWalk?"done":"due"}" id="cmd-walk"><strong>${todayWalk?"✓":"!"}</strong><span>${todayWalk?tr("Daily Walk Completed","Daily Walk Completado"):tr("Daily Walk Pending","Daily Walk Pendiente")}</span><small>${todayWalk?fmt(todayWalk.created_at):tr("Create today’s inspection","Crear inspección de hoy")}</small></button></div></section><div class="home-actions"><button class="home-action blue" id="home-new"><span class="action-icon">📷</span><span>${tr('New Observation','Nueva observación')}</span></button><button class="home-action green" id="home-observations"><span class="action-icon">☷</span><span>${tr('Observations','Observaciones')}</span></button><button class="home-action orange" id="home-corrections"><span class="action-icon">✓</span><span>${tr('Corrections','Correcciones')}</span></button><button class="home-action purple" id="home-report"><span class="action-icon">▤</span><span>${tr('Daily Report','Reporte diario')}</span></button><button class="home-action slate" id="home-team"><span class="action-icon">👥</span><span>${tr('Team','Equipo')}</span></button><button class="home-action settings" id="home-settings"><span class="action-icon">⚙</span><span>${tr('Settings','Configuración')}</span></button>${['admin','safety_director','safety'].includes(state.profile.role)?`<button class="home-action discipline" id="home-discipline"><span class="action-icon">⚠</span><span>${tr('Disciplinary Actions','Acciones de Disciplina')}</span></button>`:''}<button class="home-action safety-walk" id="home-safety-walk"><span class="action-icon">✓</span><span>${tr('Create Daily Report','Crear Daily Report')}</span></button></div><div class="home-stats"><div class="home-stat"><strong>${open}</strong>${tr('Open','Abiertas')}</div><div class="home-stat"><strong>${pending}</strong>${tr('In progress','En proceso')}</div><div class="home-stat"><strong>${closed}</strong>${tr('Closed','Cerradas')}</div></div></section><div class="mobile-bottom"><button class="active" id="bottom-home"><span>⌂</span>${tr('Home','Inicio')}</button><button id="bottom-observations"><span>📷</span>${tr('Observations','Observaciones')}</button><button id="bottom-report"><span>▤</span>${tr('Report','Reporte')}</button><button id="bottom-team"><span>👥</span>${tr('Team','Equipo')}</button></div>`);const project=document.querySelector('#home-project');if(project)project.onchange=e=>{state.project=e.target.value;render()};const goNew=()=>navigate('new'),goObs=()=>navigate('observations'),goCorrections=()=>navigate('corrections'),goReport=()=>navigate('reportCenter'),goTeam=()=>{if(state.profile.role==='admin')navigate('admin');else error(tr('Team management is available to administrators.','La administración del equipo está disponible para administradores.'))};document.querySelector('#cmd-high').onclick=goObs;document.querySelector('#cmd-mine').onclick=goObs;document.querySelector('#cmd-review').onclick=goCorrections;document.querySelector('#cmd-walk').onclick=()=>todayWalk?navigate('safetyWalkReport',todayWalk.id):navigate('safetyWalk');document.querySelector('#home-new').onclick=goNew;document.querySelector('#home-observations').onclick=goObs;document.querySelector('#home-corrections').onclick=goCorrections;document.querySelector('#home-report').onclick=goReport;document.querySelector('#home-team').onclick=goTeam;document.querySelector('#home-settings').onclick=()=>navigate('setPassword');const disciplineBtn=document.querySelector('#home-discipline');if(disciplineBtn)disciplineBtn.onclick=()=>navigate('discipline');document.querySelector('#home-safety-walk').onclick=()=>navigate('safetyWalk');document.querySelector('#bottom-home').onclick=()=>render();document.querySelector('#bottom-observations').onclick=goObs;document.querySelector('#bottom-report').onclick=goReport;document.querySelector('#bottom-team').onclick=goTeam}
function observationsList(){const rows=state.observations.filter(o=>o.project_id===state.project),counts={open:rows.filter(o=>o.status==='open').length,pending:rows.filter(o=>o.status==='pending_verification').length,closed:rows.filter(o=>o.status==='closed').length};frame(`<section class="observations-shell"><div class="section-heading"><div><h1>${tr('Safety Observations','Observaciones de seguridad')}</h1><p>${tr('Track hazards, corrections and Safety verification.','Controla peligros, correcciones y verificación de Safety.')}</p></div><button id="obs-new">+ ${tr('New Observation','Nueva observación')}</button></div><div class="obs-summary"><button class="summary-chip active" data-status="all"><strong>${rows.length}</strong>${tr('All','Todas')}</button><button class="summary-chip" data-status="open"><strong>${counts.open}</strong>${tr('Open','Abiertas')}</button><button class="summary-chip" data-status="pending_verification"><strong>${counts.pending}</strong>${tr('In Progress','En proceso')}</button><button class="summary-chip" data-status="closed"><strong>${counts.closed}</strong>${tr('Closed','Cerradas')}</button></div><div class="obs-tools"><input id="obs-search" type="search" placeholder="${tr('Search area, category or observation...','Buscar área, categoría u observación...')}"><select id="obs-priority"><option value="all">${tr('All priorities','Todas las prioridades')}</option><option value="high">${tr('High priority','Prioridad alta')}</option><option value="medium">${tr('Medium priority','Prioridad media')}</option><option value="low">${tr('Low priority','Prioridad baja')}</option></select></div><div id="obs-list" class="obs-list"></div></section>`);let status='all';const paint=()=>{const q=document.querySelector('#obs-search').value.trim().toLowerCase(),priority=document.querySelector('#obs-priority').value,list=document.querySelector('#obs-list');const filtered=rows.filter(o=>(status==='all'||o.status===status)&&(priority==='all'||o.priority===priority)&&(!q||[o.area,o.category,o.description,o.assignee?.name].some(v=>String(v||'').toLowerCase().includes(q))));list.innerHTML=filtered.length?filtered.map(o=>`<button class="obs-card" data-id="${o.id}"><div class="obs-card-top"><span class="badge ${esc(o.priority)}">${o.priority==='high'?tr('HIGH','ALTA'):o.priority==='medium'?tr('MEDIUM','MEDIA'):tr('LOW','BAJA')}</span><span class="obs-status">${o.status==='pending_verification'?tr('IN PROGRESS','EN PROCESO'):o.status==='closed'?tr('CLOSED','CERRADA'):tr('OPEN','ABIERTA')}</span></div><h3>${esc(o.area)}</h3><p class="obs-category">${esc(o.category)}</p><p>${esc(o.description)}</p><div class="obs-meta"><span>${esc(o.assignee?.name||tr('Unassigned','Sin asignar'))}</span><span>${fmt(o.created_at)}</span></div></button>`).join(''):`<div class="empty-state"><strong>${tr('No observations found','No se encontraron observaciones')}</strong><p>${tr('Change the filters or create a new observation.','Cambia los filtros o crea una nueva observación.')}</p></div>`;list.querySelectorAll('[data-id]').forEach(el=>el.onclick=async()=>{state.detail=el.dataset.id;await markViewed(state.detail);navigate('detail',state.detail)})};document.querySelector('#obs-new').onclick=()=>navigate('new');document.querySelector('#obs-search').oninput=paint;document.querySelector('#obs-priority').onchange=paint;document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{status=b.dataset.status;document.querySelectorAll('[data-status]').forEach(x=>x.classList.toggle('active',x===b));paint()});paint()}
function correctionsList(){const rows=state.observations.filter(o=>o.project_id===state.project&&o.status==='pending_verification');frame(`<section class="observations-shell"><div class="section-heading"><div><h1>${tr('Corrections','Correcciones')}</h1><p>${tr('Review completed corrective actions before final closure.','Revisa las acciones correctivas completadas antes del cierre final.')}</p></div></div><div class="review-banner"><strong>${rows.length}</strong><span>${tr('Awaiting Safety review','Esperando revisión de Safety')}</span></div><div class="obs-list">${rows.length?rows.map(o=>`<button class="obs-card correction-card" data-id="${o.id}"><div class="obs-card-top"><span class="badge ${esc(o.priority)}">${o.priority==='high'?tr('HIGH','ALTA'):o.priority==='medium'?tr('MEDIUM','MEDIA'):tr('LOW','BAJA')}</span><span class="obs-status">${tr('READY FOR REVIEW','LISTA PARA REVISIÓN')}</span></div><h3>${esc(o.area)}</h3><p class="obs-category">${esc(o.category)}</p><p>${esc(o.description)}</p><div class="obs-meta"><span>${esc(o.assignee?.name||tr('Unassigned','Sin asignar'))}</span><span>${fmt(o.created_at)}</span></div></button>`).join(''):`<div class="empty-state"><strong>${tr('No corrections awaiting review','No hay correcciones esperando revisión')}</strong><p>${tr('Completed corrections will appear here automatically.','Las correcciones completadas aparecerán aquí automáticamente.')}</p></div>`}</div></section>`);document.querySelectorAll('[data-id]').forEach(el=>el.onclick=async()=>{state.detail=el.dataset.id;await markViewed(state.detail);navigate('detail',state.detail)})}
