async function safetyWalk(){if(!['admin','safety_director','safety','supervisor'].includes(state.profile.role))return error(tr('You do not have permission to create this report.','No tiene permiso para crear este reporte.'));const project=state.projects.find(p=>p.id===state.project)||{};frame('<section class="observations-shell safety-walk-shell"><div class="section-heading"><div><h1>'+tr('Create Daily Report','Crear Daily Report')+'</h1><p>'+tr('Daily Safety Walk — one inspection for conditions, hazards, corrections and photos.','Daily Safety Walk — una inspección para condiciones, peligros, correcciones y fotos.')+'</p></div></div><div class="walk-meta"><div><small>'+tr('PROJECT','PROYECTO')+'</small><strong>'+esc(project.name||'—')+'</strong></div><div><small>'+tr('CREATED BY','CREADO POR')+'</small><strong>'+esc(state.profile.name||state.profile.email)+'</strong></div><div><small>'+tr('DATE / TIME','FECHA / HORA')+'</small><strong>'+esc(fmt(new Date().toISOString()))+'</strong></div></div><form id="walk-form"><div class="walk-legend"><span>✓ '+tr('Safe','Seguro')+'</span><span>! '+tr('Unsafe','No seguro')+'</span><span>— N/A</span></div><div class="walk-items">'+SAFETY_WALK_ITEMS.map((x,i)=>'<section class="walk-item"><div class="walk-item-head"><div><span class="walk-number">'+(i+1)+'</span><h3>'+esc(x[0])+'</h3><p>'+esc(x[1])+'</p></div><div class="walk-status"><label><input type="radio" name="status_'+i+'" value="safe" checked> ✓ '+tr('Safe','Seguro')+'</label><label><input type="radio" name="status_'+i+'" value="unsafe"> ! '+tr('Unsafe','No seguro')+'</label><label><input type="radio" name="status_'+i+'" value="na"> N/A</label></div></div><div class="walk-details"><label>'+tr('Hazard / Finding','Peligro / Hallazgo')+'<textarea name="hazard_'+i+'" maxlength="1200"></textarea></label><label>'+tr('Correction / Action Taken','Corrección / Acción tomada')+'<textarea name="correction_'+i+'" maxlength="1200"></textarea></label><label>'+tr('Photos','Fotos')+'<input type="file" name="photos_'+i+'" accept="image/jpeg,image/png,image/webp,image/heic" multiple></label></div></section>').join('')+'</div><section class="card walk-final"><label>'+tr('Overall jobsite condition','Condición general del jobsite')+'<select name="overall_status"><option value="safe">'+tr('Safe','Seguro')+'</option><option value="needs_attention">'+tr('Needs Attention','Necesita atención')+'</option><option value="unsafe">'+tr('Unsafe — Immediate Action Required','No seguro — Acción inmediata requerida')+'</option></select></label><label>'+tr('Inspector summary / notes','Resumen / notas del inspector')+'<textarea name="notes" maxlength="3000"></textarea></label><button>'+tr('Complete Daily Safety Walk','Completar Daily Safety Walk')+'</button></section></form></section>');document.querySelector('#walk-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.target,b=form.querySelector('button'),d=new FormData(form);b.disabled=true;const w=await db.from('daily_safety_walks').insert({project_id:state.project,created_by:state.profile.id,overall_status:d.get('overall_status'),notes:d.get('notes')||null}).select('id').single();if(w.error){b.disabled=false;return error(w.error)}for(let i=0;i<SAFETY_WALK_ITEMS.length;i++){const status=d.get('status_'+i),hazard=String(d.get('hazard_'+i)||'').trim(),correction=String(d.get('correction_'+i)||'').trim();const item=await db.from('daily_safety_walk_items').insert({walk_id:w.data.id,category:SAFETY_WALK_ITEMS[i][0],item_text:SAFETY_WALK_ITEMS[i][1],status,hazard:hazard||null,correction:correction||null,sort_order:i}).select('id').single();if(item.error){b.disabled=false;return error(item.error)}const input=form.querySelector('[name="photos_'+i+'"]'),files=[...input.files];for(const file of files){if(file.size>10485760){b.disabled=false;return error(tr('Each photo must be 10 MB or less.','Cada foto debe pesar 10 MB o menos.'))}const ext=(file.name.split('.').pop()||'jpg').toLowerCase(),path=w.data.id+'/'+item.data.id+'/'+crypto.randomUUID()+'.'+ext,up=await db.storage.from('daily-safety-walks').upload(path,file,{contentType:file.type||'image/jpeg'});if(up.error){b.disabled=false;return error(up.error)}const p=await db.from('daily_safety_walk_photos').insert({item_id:item.data.id,path,kind:status==='unsafe'?'hazard':'correction',uploaded_by:state.profile.id});if(p.error){b.disabled=false;return error(p.error)}}}b.disabled=false;navigate('safetyWalkReport',w.data.id)}}
async function safetyWalkReport(){const id=state.detail;if(!id)return navigate('home',null,{replace:true});const q=await db.from('daily_safety_walks').select('*,creator:profiles!daily_safety_walks_created_by_fkey(name,email),items:daily_safety_walk_items(*,photos:daily_safety_walk_photos(id,path,kind))').eq('id',id).single();if(q.error)return error(q.error);const w=q.data,project=state.projects.find(p=>p.id===w.project_id)||{},items=[...(w.items||[])].sort((a,b)=>a.sort_order-b.sort_order);for(const item of items){item.urls=[];for(const p of item.photos||[]){const s=await db.storage.from('daily-safety-walks').createSignedUrl(p.path,3600);if(!s.error&&s.data?.signedUrl)item.urls.push(s.data.signedUrl)}}const unsafeItems=items.filter(x=>x.status==='unsafe'),safe=items.filter(x=>x.status==='safe').length,unsafe=unsafeItems.length,na=items.filter(x=>x.status==='na').length,total=items.length,reviewed=total-na,compliance=reviewed?Math.round(safe/reviewed*100):100,corrected=unsafeItems.filter(x=>x.correction).length,openHazards=unsafeItems.filter(x=>!x.correction).length,photoCount=items.reduce((n,x)=>n+x.urls.length,0),when=new Date(w.created_at),dateText=new Intl.DateTimeFormat(state.lang==='es'?'es-US':'en-US',{weekday:'long',year:'numeric',month:'long',day:'numeric'}).format(when),timeText=new Intl.DateTimeFormat(state.lang==='es'?'es-US':'en-US',{hour:'numeric',minute:'2-digit'}).format(when),statusLabel=w.overall_status==='safe'?tr('SAFE','SEGURO'):w.overall_status==='unsafe'?tr('UNSAFE — IMMEDIATE ACTION REQUIRED','NO SEGURO — ACCIÓN INMEDIATA'):tr('NEEDS ATTENTION','NECESITA ATENCIÓN'),reportNo='DSW-'+localDateKey(when).replaceAll('-','')+'-'+String(w.id).slice(0,6).toUpperCase();const status=x=>x==='safe'?tr('SAFE','SEGURO'):x==='unsafe'?tr('UNSAFE','NO SEGURO'):'N/A';frame('<div class="no-print report-actions walk-print-actions"><button class="secondary" id="back">← '+tr('Back','Atrás')+'</button><button id="print">▤ '+tr('Download / Print PDF','Descargar / Imprimir PDF')+'</button></div><article class="report professional-report executive-walk-report"><header class="ewr-header"><div class="ewr-brand"><img src="/ge-logo.png" alt="G&E Florida Contractors"><div><strong>G&E FLORIDA CONTRACTORS</strong><span>SAFETY DEPARTMENT</span></div></div><div class="ewr-document"><small>'+tr('OFFICIAL FIELD INSPECTION','INSPECCIÓN OFICIAL DE CAMPO')+'</small><h1>'+tr('DAILY SAFETY WALK REPORT','REPORTE DAILY SAFETY WALK')+'</h1><p>'+tr('Construction Safety Inspection & Corrective Action Record','Registro de Inspección de Seguridad y Acción Correctiva')+'</p></div><div class="ewr-id"><small>'+tr('REPORT NO.','REPORTE NO.')+'</small><strong>'+esc(reportNo)+'</strong><span>'+esc(localDateKey(when))+'</span></div></header><section class="ewr-project"><div class="wide"><small>'+tr('PROJECT / JOBSITE','PROYECTO / JOBSITE')+'</small><strong>'+esc(project.name||'—')+'</strong><span>'+esc(project.address||tr('Address not entered','Dirección no registrada'))+'</span></div><div><small>'+tr('GENERAL CONTRACTOR','CONTRATISTA GENERAL')+'</small><strong>'+esc(project.general_contractor||'—')+'</strong></div><div><small>'+tr('INSPECTED / PREPARED BY','INSPECCIONADO / PREPARADO POR')+'</small><strong>'+esc(w.creator?.name||w.creator?.email||'—')+'</strong></div><div><small>'+tr('INSPECTION DATE','FECHA DE INSPECCIÓN')+'</small><strong>'+esc(dateText)+'</strong></div><div><small>'+tr('INSPECTION TIME','HORA DE INSPECCIÓN')+'</small><strong>'+esc(timeText)+'</strong></div></section><section class="ewr-executive"><div class="ewr-executive-title"><div><small>'+tr('EXECUTIVE SAFETY SUMMARY','RESUMEN EJECUTIVO DE SEGURIDAD')+'</small><h2>'+statusLabel+'</h2></div><div class="ewr-score"><strong>'+compliance+'%</strong><span>'+tr('Safe items reviewed','Ítems revisados seguros')+'</span></div></div><div class="ewr-kpis"><div><strong>'+total+'</strong><span>'+tr('Checklist Items','Ítems inspeccionados')+'</span></div><div class="safe"><strong>'+safe+'</strong><span>'+tr('Safe','Seguro')+'</span></div><div class="unsafe"><strong>'+unsafe+'</strong><span>'+tr('Unsafe','No seguro')+'</span></div><div><strong>'+corrected+'</strong><span>'+tr('Corrections Documented','Correcciones documentadas')+'</span></div><div class="open"><strong>'+openHazards+'</strong><span>'+tr('Open Hazards','Peligros abiertos')+'</span></div><div><strong>'+photoCount+'</strong><span>'+tr('Evidence Photos','Fotos de evidencia')+'</span></div></div>'+(w.notes?'<div class="ewr-inspector-note"><small>'+tr('INSPECTOR SUMMARY','RESUMEN DEL INSPECTOR')+'</small><p>'+esc(w.notes)+'</p></div>':'')+'</section><section class="ewr-section"><div class="ewr-section-title"><span>01</span><div><h2>'+tr('Inspection Checklist Summary','Resumen del Checklist de Inspección')+'</h2><p>'+tr('Status of every safety category reviewed during this field walk.','Estado de cada categoría de seguridad revisada durante la caminata.')+'</p></div></div><div class="ewr-table"><div class="ewr-tr ewr-th"><span>#</span><span>'+tr('Safety Category','Categoría de Seguridad')+'</span><span>'+tr('Status','Estado')+'</span><span>'+tr('Finding / Correction','Hallazgo / Corrección')+'</span></div>'+items.map((x,i)=>'<div class="ewr-tr"><span>'+(i+1)+'</span><span><strong>'+esc(x.category)+'</strong><small>'+esc(x.item_text)+'</small></span><span><b class="ewr-status '+x.status+'">'+status(x.status)+'</b></span><span>'+esc(x.hazard||x.correction||tr('No adverse finding documented.','Sin hallazgo adverso documentado.'))+'</span></div>').join('')+'</div></section>'+(unsafeItems.length?'<section class="ewr-section"><div class="ewr-section-title"><span>02</span><div><h2>'+tr('Hazards & Corrective Actions','Peligros y Acciones Correctivas')+'</h2><p>'+tr('Detailed record of unsafe conditions identified and actions documented.','Registro detallado de condiciones no seguras identificadas y acciones documentadas.')+'</p></div></div>'+unsafeItems.map((x,i)=>'<article class="ewr-hazard"><header><div><small>'+tr('HAZARD','PELIGRO')+' '+(i+1)+'</small><h3>'+esc(x.category)+'</h3></div><b class="ewr-status unsafe">'+tr('UNSAFE','NO SEGURO')+'</b></header><div class="ewr-hazard-grid"><div><small>'+tr('CONDITION / FINDING','CONDICIÓN / HALLAZGO')+'</small><p>'+esc(x.hazard||tr('Unsafe status recorded; no additional description entered.','Estado no seguro registrado; no se ingresó descripción adicional.'))+'</p></div><div><small>'+tr('CORRECTIVE ACTION / CONTROL','ACCIÓN CORRECTIVA / CONTROL')+'</small><p>'+esc(x.correction||tr('Corrective action pending / not documented.','Acción correctiva pendiente / no documentada.'))+'</p></div></div>'+(x.urls.length?'<div class="ewr-evidence"><small>'+tr('PHOTO EVIDENCE','EVIDENCIA FOTOGRÁFICA')+'</small><div class="report-photos">'+x.urls.map((u,j)=>'<figure><img src="'+esc(u)+'" alt="Safety evidence"><figcaption>'+tr('Evidence Photo','Foto de evidencia')+' '+(j+1)+' · '+esc(x.category)+'</figcaption></figure>').join('')+'</div></div>':'')+'</article>').join('')+'</section>':'')+'<section class="ewr-section"><div class="ewr-section-title"><span>'+(unsafeItems.length?'03':'02')+'</span><div><h2>'+tr('Inspection Closeout','Cierre de Inspección')+'</h2><p>'+tr('Acknowledgment of the field inspection record and documented findings.','Reconocimiento del registro de inspección de campo y hallazgos documentados.')+'</p></div></div><div class="ewr-closeout"><div><small>'+tr('OVERALL JOBSITE CONDITION','CONDICIÓN GENERAL DEL JOBSITE')+'</small><strong>'+statusLabel+'</strong></div><div><small>'+tr('OPEN HAZARDS REQUIRING FOLLOW-UP','PELIGROS ABIERTOS QUE REQUIEREN SEGUIMIENTO')+'</small><strong>'+openHazards+'</strong></div><div><small>'+tr('REPORT GENERATED','REPORTE GENERADO')+'</small><strong>'+esc(dateText)+' · '+esc(timeText)+'</strong></div></div><div class="ewr-signatures"><div><span></span><strong>'+esc(w.creator?.name||'—')+'</strong><small>'+tr('Safety Inspector / Prepared By','Inspector de Seguridad / Preparado por')+'</small></div><div><span></span><strong>&nbsp;</strong><small>'+tr('Supervisor / Foreman Acknowledgment','Reconocimiento Supervisor / Foreman')+'</small></div></div><div class="ewr-note">'+tr('This report documents conditions observed during the field walk and corrective actions recorded at the time of inspection. Items requiring follow-up should remain tracked until resolved.','Este reporte documenta las condiciones observadas durante la caminata y las acciones correctivas registradas al momento de la inspección. Los asuntos que requieren seguimiento deben mantenerse controlados hasta su resolución.')+'</div></section><footer class="ewr-footer"><div><img src="/ge-logo.png" alt=""><span><strong>G&E Safety Department</strong><br>'+tr('Safety Today. A Safer Tomorrow.','Seguridad hoy. Un mañana más seguro.')+'</span></div><div><strong>'+esc(reportNo)+'</strong><br>'+tr('Daily Safety Walk — Field Inspection Record','Daily Safety Walk — Registro de Inspección de Campo')+'</div></footer></article>');document.querySelector('#back').onclick=back;document.querySelector('#print').onclick=()=>window.print()}
async function discipline(){if(!['admin','safety_director','safety'].includes(state.profile.role)){navigate('home',null,{replace:true});return}const [members,records]=await Promise.all([db.from('project_members').select('user_id, profile:profiles(id,name,email,position)').eq('project_id',state.project),db.from('safety_discipline').select('*, employee:profiles!safety_discipline_employee_id_fkey(name,email), issuer:profiles!safety_discipline_created_by_fkey(name), photos:discipline_photos(id,path)').eq('project_id',state.project).order('incident_date',{ascending:false})]);if(members.error||records.error)return error(members.error||records.error);const actions=[['coaching',tr('Safety Coaching / Counseling','Orientación / Consejería de seguridad')],['verbal_warning',tr('Verbal Warning','Advertencia verbal')],['written_warning',tr('Written Warning','Advertencia escrita')],['final_warning',tr('Final Written Warning','Advertencia escrita final')],['removal_suspension',tr('Removal from Task / Suspension','Retiro de la tarea / Suspensión')]];frame(`<section class="observations-shell discipline-shell"><div class="section-heading"><div><h1>${tr('Employee Safety Discipline','Disciplina de seguridad del trabajador')}</h1><p>${tr('Document violations of established safety rules consistently. Never use discipline for reporting an injury, illness, hazard or safety concern.','Documenta de forma consistente las violaciones de reglas de seguridad establecidas. Nunca uses disciplina por reportar una lesión, enfermedad, peligro o preocupación de seguridad.')}</p></div></div><div class="discipline-notice"><strong>${tr('Important OSHA safeguard','Protección importante de OSHA')}</strong><span>${tr('Discipline must address the rule violation—not the act of reporting an injury or hazard.','La disciplina debe responder a la violación de la regla, no al hecho de reportar una lesión o un peligro.')}</span></div><section class="card"><h2>${tr('New disciplinary record','Nuevo registro disciplinario')}</h2><form id="discipline-form"><label>${tr('Employee name','Nombre del trabajador')}<input name="employee_name" required maxlength="160" placeholder="${tr('Full name','Nombre completo')}"></label><label>${tr('Position / Trade','Posición / Oficio')}<input name="employee_position" required maxlength="120" placeholder="${tr('Example: Foreman, Laborer, Carpenter','Ejemplo: Foreman, Laborer, Carpenter')}"></label><label>${tr('Age','Edad')}<input name="employee_age" type="number" min="14" max="100" required></label><div id="employee-discipline-summary" class="employee-discipline-summary"><div><small>${tr('POSITION / TRADE','POSICIÓN / OFICIO')}</small><strong id="employee-position">—</strong></div><div><small>${tr('DISCIPLINARY ACTIONS','ACCIONES DE DISCIPLINA')}</small><strong id="employee-discipline-count">0</strong></div><div><small>${tr('LAST ACTION','ÚLTIMA ACCIÓN')}</small><strong id="employee-last-action">—</strong></div><div id="employee-history-preview" class="employee-history-preview"></div></div><label>${tr('Safety rule / violation','Regla / violación de seguridad')}<select name="violation_type" required><option>Fall Protection</option><option>PPE</option><option>Ladders / Stairways</option><option>Scaffolds / Swing Stage</option><option>Electrical</option><option>Tools / Power Tools</option><option>Cranes / Rigging</option><option>Forklift / Heavy Equipment</option><option>Housekeeping</option><option>Traffic Control / MOT</option><option>Unauthorized Unsafe Act</option><option>Failure to Follow Safety Instruction</option><option>Other</option></select></label><label>${tr('Facts observed','Hechos observados')}<textarea name="description" required maxlength="3000" placeholder="${tr('Describe the specific rule, what was observed, location and circumstances.','Describa la regla específica, lo observado, lugar y circunstancias.')}"></textarea></label><label>${tr('Disciplinary action','Acción disciplinaria')}<select name="action_level" required>${actions.map(a=>`<option value="${a[0]}">${a[1]}</option>`).join('')}</select></label><label class="check-line"><input type="checkbox" name="retraining_required"> ${tr('Safety retraining required','Reentrenamiento de seguridad requerido')}</label><label>${tr('Retraining topic','Tema del reentrenamiento')}<input name="retraining_topic" maxlength="250"></label><label>${tr('Employee comments','Comentarios del trabajador')}<textarea name="employee_comments" maxlength="2000"></textarea></label><label>${tr('Photo evidence','Evidencia fotográfica')}<input name="evidence" type="file" accept="image/jpeg,image/png,image/webp,image/heic" multiple></label><small>${tr('Select one or multiple photos from your phone or tablet photo gallery. Maximum 10 MB each.','Seleccione una o varias fotos desde la galería de su teléfono o tablet. Máximo 10 MB cada una.')}</small><button>${tr('Save disciplinary record','Guardar registro disciplinario')}</button></form></section><section class="card"><h2>${tr('Discipline history','Historial disciplinario')}</h2><div class="discipline-history">${records.data.length?records.data.map(r=>`<div class="discipline-record"><div><strong>${esc(r.employee_name||r.employee?.name||r.employee?.email||'—')}</strong><span>${esc(fmt(r.incident_date))}</span></div><span class="badge">${esc(actions.find(a=>a[0]===r.action_level)?.[1]||r.action_level)}</span><p><b>${esc(r.violation_type)}</b> — ${esc(r.description)}</p><small>${tr('Issued by','Emitido por')}: ${esc(r.issuer?.name||'—')}${r.retraining_required?' · '+tr('Retraining required','Reentrenamiento requerido'):''} · 📷 ${(r.photos||[]).length} ${tr('photo(s)','foto(s)')}</small><div class="discipline-record-actions"><button type="button" class="secondary discipline-report-btn" data-record="${r.id}">▤ ${tr('View / Print Report','Ver / Imprimir Reporte')}</button>${(r.photos||[]).length?`<button type="button" class="secondary discipline-evidence-btn" data-record="${r.id}">${tr('View evidence','Ver evidencia')}</button>`:''}</div></div>`).join(''):`<div class="empty-state">${tr('No disciplinary records for this project.','No hay registros disciplinarios para este proyecto.')}</div>`}</div></section></section>`);const employeeName=document.querySelector('[name="employee_name"]'),employeePositionInput=document.querySelector('[name="employee_position"]'),employeePosition=document.querySelector('#employee-position'),employeeCount=document.querySelector('#employee-discipline-count'),employeeLast=document.querySelector('#employee-last-action'),employeeHistory=document.querySelector('#employee-history-preview');const paintEmployeeHistory=()=>{const name=employeeName.value.trim().toLowerCase(),history=name?records.data.filter(r=>(r.employee_name||r.employee?.name||'').trim().toLowerCase()===name):[];employeePosition.textContent=employeePositionInput.value.trim()||tr('Not specified','No especificada');employeeCount.textContent=String(history.length);employeeLast.textContent=history.length?fmt(history[0].incident_date):'—';employeeHistory.innerHTML=history.length?`<small>${tr('Previous records','Registros anteriores')}</small>${history.slice(0,5).map(r=>`<div><span>${esc(fmt(r.incident_date))}</span><b>${esc(r.violation_type)}</b><span>${esc(actions.find(a=>a[0]===r.action_level)?.[1]||r.action_level)}</span></div>`).join('')}`:''};employeeName.oninput=paintEmployeeHistory;employeePositionInput.oninput=paintEmployeeHistory;paintEmployeeHistory();document.querySelectorAll('.discipline-report-btn').forEach(btn=>btn.onclick=()=>navigate('disciplineReport',btn.dataset.record));document.querySelectorAll('.discipline-evidence-btn').forEach(btn=>btn.onclick=async()=>{const rec=records.data.find(x=>x.id===btn.dataset.record);if(!rec)return;const urls=[];for(const p of rec.photos||[]){const s=await db.storage.from('discipline-evidence').createSignedUrl(p.path,300);if(!s.error&&s.data?.signedUrl)urls.push(s.data.signedUrl)}const w=window.open('','_blank');if(!w)return error(tr('Allow pop-ups to view evidence.','Permita ventanas emergentes para ver la evidencia.'));w.document.write(`<title>${tr('Disciplinary Evidence','Evidencia Disciplinaria')}</title><style>body{font-family:Arial;margin:24px;background:#f4f6f8}h1{color:#102a43}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}img{width:100%;max-height:520px;object-fit:contain;background:#fff;border-radius:12px;box-shadow:0 3px 14px #0002}</style><h1>${tr('Disciplinary Evidence','Evidencia Disciplinaria')}</h1><div class="grid">${urls.map(u=>`<img src="${u}" alt="Evidence">`).join('')}</div>`);w.document.close()});document.querySelector('#discipline-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.target,b=form.querySelector('button'),d=new FormData(form);b.disabled=true;const r=await db.from('safety_discipline').insert({project_id:state.project,employee_id:null,employee_name:String(d.get('employee_name')).trim(),employee_position:String(d.get('employee_position')).trim(),employee_age:Number(d.get('employee_age')),created_by:state.profile.id,violation_type:d.get('violation_type'),description:d.get('description'),action_level:d.get('action_level'),retraining_required:d.get('retraining_required')==='on',retraining_topic:d.get('retraining_topic')||null,employee_comments:d.get('employee_comments')||null,incident_date:new Date().toISOString()}).select('id').single();if(r.error){b.disabled=false;return error(r.error)}const files=[...form.querySelector('[name=evidence]').files];for(const file of files){if(file.size>10485760){b.disabled=false;return error(tr('Each photo must be 10 MB or less.','Cada foto debe pesar 10 MB o menos.'))}const ext=(file.name.split('.').pop()||'jpg').toLowerCase(),path=`${r.data.id}/${crypto.randomUUID()}.${ext}`,up=await db.storage.from('discipline-evidence').upload(path,file,{contentType:file.type||'image/jpeg'});if(up.error){b.disabled=false;return error(up.error)}const meta=await db.from('discipline_photos').insert({discipline_id:r.data.id,path,uploaded_by:state.profile.id});if(meta.error){b.disabled=false;return error(meta.error)}}b.disabled=false;navigate('disciplineReport',r.data.id)}}

async function disciplineReport(){const id=state.detail;if(!id){navigate('discipline',null,{replace:true});return}const {data:r,error:err}=await db.from('safety_discipline').select('*, issuer:profiles!safety_discipline_created_by_fkey(name), photos:discipline_photos(id,path)').eq('id',id).single();if(err)return error(err);const project=state.projects.find(p=>p.id===r.project_id)||{},urls=[];for(const p of r.photos||[]){const s=await db.storage.from('discipline-evidence').createSignedUrl(p.path,3600);if(!s.error&&s.data?.signedUrl)urls.push(s.data.signedUrl)}const when=new Date(r.incident_date),dateText=new Intl.DateTimeFormat(state.lang==='es'?'es-US':'en-US',{weekday:'long',year:'numeric',month:'long',day:'numeric'}).format(when),timeText=new Intl.DateTimeFormat(state.lang==='es'?'es-US':'en-US',{hour:'numeric',minute:'2-digit'}).format(when);frame(`<div class="no-print report-actions"><button class="secondary" id="back">← ${tr('Back','Atrás')}</button><button id="print">▤ ${tr('Download / Print PDF','Descargar / Imprimir PDF')}</button></div><article class="report professional-report discipline-report"><header class="report-header"><img src="/ge-logo.png" alt="G&E Florida Contractors"><div class="report-title"><span>G&E FLORIDA CONTRACTORS</span><h1>${tr('Employee Disciplinary Action Notice','Aviso de Acción Disciplinaria')}</h1><p>G&E Safety Department</p></div><div class="report-number"><small>${tr('DATE','FECHA')}</small><strong>${esc(localDateKey(when))}</strong></div></header><section class="report-info"><div><small>${tr('EMPLOYEE','TRABAJADOR')}</small><strong>${esc(r.employee_name||'—')}</strong></div><div><small>${tr('POSITION / TRADE','POSICIÓN / OFICIO')}</small><strong>${esc(r.employee_position||'—')}</strong></div><div><small>${tr('AGE','EDAD')}</small><strong>${esc(r.employee_age||'—')}</strong></div><div><small>${tr('PROJECT / JOBSITE','PROYECTO / JOBSITE')}</small><strong>${esc(project.name||'—')}</strong></div><div><small>${tr('DATE','FECHA')}</small><strong>${esc(dateText)}</strong></div><div><small>${tr('TIME','HORA')}</small><strong>${esc(timeText)}</strong></div></section><section class="discipline-report-section"><small>${tr('SAFETY RULE / VIOLATION','REGLA / VIOLACIÓN DE SEGURIDAD')}</small><h2>${esc(r.violation_type)}</h2><p>${esc(r.description)}</p></section><section class="discipline-report-section"><small>${tr('DISCIPLINARY ACTION','ACCIÓN DISCIPLINARIA')}</small><h2>${esc(r.action_level.replaceAll('_',' '))}</h2>${r.retraining_required?`<p><b>${tr('Safety retraining required','Reentrenamiento de seguridad requerido')}:</b> ${esc(r.retraining_topic||'—')}</p>`:''}</section>${r.employee_comments?`<section class="discipline-report-section"><small>${tr('EMPLOYEE COMMENTS','COMENTARIOS DEL TRABAJADOR')}</small><p>${esc(r.employee_comments)}</p></section>`:''}${urls.length?`<section class="discipline-report-section"><small>${tr('PHOTO EVIDENCE','EVIDENCIA FOTOGRÁFICA')}</small><div class="report-photos">${urls.map(u=>`<figure><img src="${esc(u)}" alt="Evidence"><figcaption>${tr('DISCIPLINARY EVIDENCE','EVIDENCIA DISCIPLINARIA')}</figcaption></figure>`).join('')}</div></section>`:''}<section class="discipline-signatures"><div><span></span><small>${tr('Employee Signature','Firma del trabajador')}</small></div><div><span></span><small>${tr('Safety / Issued by','Safety / Emitido por')}: ${esc(r.issuer?.name||'—')}</small></div></section><footer class="report-footer"><div><strong>G&E Safety Department</strong><br><span>${tr('Safety Today. A Safer Tomorrow.','Seguridad hoy. Un mañana más seguro.')}</span></div><div>${tr('Generated automatically from the disciplinary record.','Generado automáticamente desde el registro disciplinario.')}</div></footer></article>`);document.querySelector('#back').onclick=back;document.querySelector('#print').onclick=()=>window.print()}

async function newObservation(){const members=await db.from('project_members').select('user_id, profile:profiles(name)').eq('project_id',state.project);if(members.error)return error(members.error);frame(`<button class="secondary" id="back">← ${tr('Back','Atrás')}</button><section class="card"><h1>${tr('New observation','Nueva observación')}</h1><form id="observation"><label>${tr('Area','Área')}<input name="area" required maxlength="120"></label><label>${tr('Category','Categoría')}<select name="category"><option value="Fall Protection">${tr('Fall Protection','Protección contra caídas')}</option><option value="Guardrails / Floor Openings">${tr('Guardrails / Floor Openings','Barandas / Aberturas de piso')}</option><option value="Ladders / Stairways">${tr('Ladders / Stairways','Escaleras / Escalinatas')}</option><option value="Scaffolds / Swing Stage">${tr('Scaffolds / Swing Stage','Andamios / Swing Stage')}</option><option value="Electrical">${tr('Electrical','Eléctrico')}</option><option value="Struck-By / Falling Objects">${tr('Struck-By / Falling Objects','Golpeado por / Objetos que caen')}</option><option value="Caught-In / Between">${tr('Caught-In / Between','Atrapado entre / dentro')}</option><option value="PPE">${tr('PPE','EPP / Equipo de protección personal')}</option><option value="Housekeeping">${tr('Housekeeping','Limpieza y orden')}</option><option value="Tools / Power Tools">${tr('Tools / Power Tools','Herramientas / Herramientas eléctricas')}</option><option value="Cranes / Hoisting">${tr('Cranes / Hoisting','Grúas / Izaje')}</option><option value="Rigging / Material Handling">${tr('Rigging / Material Handling','Rigging / Manejo de materiales')}</option><option value="Forklift / Telehandler">${tr('Forklift / Telehandler','Montacargas / Telehandler')}</option><option value="Aerial Lift / MEWP">${tr('Aerial Lift / MEWP','Plataforma aérea / MEWP')}</option><option value="Motor Vehicles / Heavy Equipment">${tr('Motor Vehicles / Heavy Equipment','Vehículos / Equipo pesado')}</option><option value="Excavation / Trenching">${tr('Excavation / Trenching','Excavación / Zanjas')}</option><option value="Concrete / Masonry">${tr('Concrete / Masonry','Concreto / Mampostería')}</option><option value="Steel Erection">${tr('Steel Erection','Erección de acero')}</option><option value="Welding / Cutting / Hot Work">${tr('Welding / Cutting / Hot Work','Soldadura / Corte / Trabajo en caliente')}</option><option value="Fire Prevention / Flammables">${tr('Fire Prevention / Flammables','Prevención de incendios / Inflamables')}</option><option value="Hazard Communication / Chemicals">${tr('Hazard Communication / Chemicals','Comunicación de peligros / Químicos')}</option><option value="Silica / Dust / Respiratory">${tr('Silica / Dust / Respiratory','Sílice / Polvo / Respiratorio')}</option><option value="Noise / Hearing">${tr('Noise / Hearing','Ruido / Protección auditiva')}</option><option value="Heat Stress / Weather">${tr('Heat Stress / Weather','Estrés por calor / Clima')}</option><option value="Barricades / Signs / Access">${tr('Barricades / Signs / Access','Barricadas / Señales / Acceso')}</option><option value="Traffic Control / MOT">${tr('Traffic Control / MOT','Control de tráfico / MOT')}</option><option value="Emergency / First Aid">${tr('Emergency / First Aid','Emergencia / Primeros auxilios')}</option><option value="Sanitation / Drinking Water">${tr('Sanitation / Drinking Water','Saneamiento / Agua potable')}</option><option value="Other">${tr('Other','Otro')}</option></select></label><label>${tr('Description','Descripción')}<textarea name="description" required maxlength="2000"></textarea></label><label>${tr('Priority','Prioridad')}<select name="priority"><option value="low">${tr('Low','Baja')}</option><option value="medium">${tr('Medium','Media')}</option><option value="high">${tr('High','Alta')}</option></select></label><label>${tr('Assign to','Asignar a')}<select name="assigned_to"><option value="">${tr('Unassigned','Sin asignar')}</option>${members.data.map(m=>`<option value="${m.user_id}">${esc(m.profile?.name||m.user_id)}</option>`).join('')}</select></label><label>${tr('Foreman in Charge','Foreman encargado')}<select name="foreman_id"><option value="">${tr('Select foreman','Seleccione foreman')}</option>${members.data.map(m=>`<option value="${m.user_id}">${esc(m.profile?.name||m.user_id)}</option>`).join('')}</select></label><label>${tr('Jobsite Safety','Safety del jobsite')}<select name="jobsite_safety_id"><option value="">${tr('Select Safety','Seleccione Safety')}</option>${members.data.map(m=>`<option value="${m.user_id}">${esc(m.profile?.name||m.user_id)}</option>`).join('')}</select></label><label>${tr('Initial photo','Foto inicial')}<input name="photo" type="file" accept="image/jpeg,image/png,image/webp,image/heic" required></label><button>${tr('Submit observation','Enviar observación')}</button></form></section>`);document.querySelector('#back').onclick=back;document.querySelector('#observation').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const f=new FormData(e.target),{data:o,error:err}=await db.from('observations').insert({project_id:state.project,area:f.get('area'),category:f.get('category'),description:f.get('description'),priority:f.get('priority'),assigned_to:f.get('assigned_to')||null,foreman_id:f.get('foreman_id')||null,jobsite_safety_id:f.get('jobsite_safety_id')||null,created_by:state.profile.id}).select().single();if(err)throw err;await upload(o.id,'before',f.get('photo'));state.page='home';await load();render()}catch(err){error(err)}finally{button.disabled=false}}}
async function upload(id,kind,file){if(!(file instanceof File)||!file.size)throw Error(tr('Photo required','Se requiere una foto'));if(!file.type.startsWith('image/')||file.size>10*1024*1024)throw Error(tr('Use an image smaller than 10 MB','Use una imagen menor de 10 MB'));const path=`${id}/${crypto.randomUUID()}.${file.type.split('/')[1]?.replace(/[^a-z0-9]/gi,'')||'jpg'}`;const up=await db.storage.from('observation-photos').upload(path,file,{contentType:file.type});if(up.error)throw up.error;const r=await db.from('observation_photos').insert({observation_id:id,kind,path,uploaded_by:state.profile.id});if(r.error)throw r.error}
async function markViewed(id){await db.from('observation_views').upsert({observation_id:id,user_id:state.profile.id,last_viewed_at:new Date().toISOString()},{onConflict:'observation_id,user_id'})}
function photoUrl(path){return db.storage.from('observation-photos').createSignedUrl(path,3600)}
async function detail(){const o=state.observations.find(x=>x.id===state.detail);if(!o){state.page='home';return render()}const [photos,views,actions]=await Promise.all([db.from('observation_photos').select('*').eq('observation_id',o.id),db.from('observation_views').select('*, profile:profiles(name)').eq('observation_id',o.id),db.from('corrective_actions').select('*, author:profiles(name)').eq('observation_id',o.id).order('created_at')]);if(photos.error||views.error||actions.error)return error(photos.error||views.error||actions.error);const signed=await Promise.all(photos.data.map(async p=>({...p,url:(await photoUrl(p.path)).data?.signedUrl})));frame(`<button class="secondary" id="back">← ${tr('Observations','Observaciones')}</button><section class="card"><div class="row"><h1>${esc(o.area)}</h1><span class="badge ${o.priority}">${esc(o.priority)}</span><span class="badge">${esc(o.status)}</span></div><p>${esc(o.description)}</p><p>${esc(o.category)} · ${fmt(o.created_at)} · ${esc(o.creator?.name)}</p><div class="assignment-summary"><span><b>${tr('Assigned Person','Persona asignada')}:</b> ${esc(o.assignee?.name||tr('Unassigned','Sin asignar'))}</span><span><b>${tr('Foreman in Charge','Foreman encargado')}:</b> ${esc(o.foreman?.name||'—')}</span><span><b>${tr('Jobsite Safety','Safety del jobsite')}:</b> ${esc(o.jobsite_safety?.name||'—')}</span></div><div class="photos">${signed.map(p=>`<figure><img src="${esc(p.url)}" alt="${esc(p.kind)}"><figcaption>${p.kind==='before'?tr('Before','Antes'):tr('After','Después')}</figcaption></figure>`).join('')}</div><h2>${tr('Corrective actions','Acciones correctivas')}</h2>${actions.data.map(a=>`<p class="note">${esc(a.comment)}<br><small>${esc(a.author?.name)} · ${fmt(a.created_at)}</small></p>`).join('')}<h2>${tr('Viewed by','Visto por')}</h2>${views.data.map(v=>`<p>${esc(v.profile?.name)} · ${fmt(v.last_viewed_at)}</p>`).join('')||'<p>—</p>'}${o.status==='open'?`<form id="correction"><label>${tr('Correction comment','Comentario de corrección')}<textarea name="comment" required></textarea></label><label>${tr('After photo','Foto después')}<input name="photo" type="file" accept="image/jpeg,image/png,image/webp,image/heic" required></label><button>${tr('Send for Safety review','Enviar a revisión de Safety')}</button></form>`:''}${o.status==='pending_verification'&&['admin','safety_director','safety'].includes(state.profile.role)?`<button id="close">${tr('Verify and close','Verificar y cerrar')}</button>`:''}</section>`);document.querySelector('#back').onclick=back;const f=document.querySelector('#correction');if(f)f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button');b.disabled=true;try{const d=new FormData(f),r=await db.from('corrective_actions').insert({observation_id:o.id,comment:d.get('comment'),created_by:state.profile.id});if(r.error)throw r.error;await upload(o.id,'after',d.get('photo'));const u=await db.from('observations').update({status:'pending_verification'}).eq('id',o.id);if(u.error)throw u.error;await load();detail()}catch(err){error(err)}finally{b.disabled=false}};const c=document.querySelector('#close');if(c)c.onclick=async()=>{const r=await db.from('observations').update({status:'closed',verified_by:state.profile.id,closed_at:new Date().toISOString()}).eq('id',o.id);if(r.error)return error(r.error);await load();detail()}}

async function reportCenter(){const project=state.projects.find(p=>p.id===state.project)||{};const [walks,disc,corrections,docs]=await Promise.all([db.from('daily_safety_walks').select('id,created_at,overall_status,created_by,creator:profiles!daily_safety_walks_created_by_fkey(name)').eq('project_id',state.project).order('created_at',{ascending:false}),db.from('safety_discipline').select('id,employee_name,violation_type,action_level,incident_date,created_by,issuer:profiles!safety_discipline_created_by_fkey(name)').eq('project_id',state.project).order('incident_date',{ascending:false}),db.from('corrective_actions').select('id,observation_id,comment,created_at,created_by,author:profiles!corrective_actions_created_by_fkey(name),observation:observations!inner(id,project_id,area,category,status,priority,description)').eq('observation.project_id',state.project).order('created_at',{ascending:false}),db.from('report_documents').select('id,report_type,source_id,report_number,title,document_status,version,pdf_path,created_at,finalized_at').eq('project_id',state.project).order('created_at',{ascending:false})]);if(walks.error||disc.error||corrections.error||docs.error)return error(walks.error||disc.error||corrections.error||docs.error);const obs=state.observations.filter(o=>o.project_id===state.project).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)),todayObs=obs.filter(o=>localDateKey(o.created_at)===localDateKey()),cats=[{key:'daily',icon:'▤',title:tr('Daily Safety Reports','Reportes Diarios de Safety'),desc:tr('Professional daily project summary generated from recorded activity.','Resumen profesional diario del proyecto generado desde la actividad registrada.'),count:todayObs.length?1:0,cls:'reports-daily'},{key:'walks',icon:'☑',title:tr('Daily Safety Walks','Daily Safety Walks'),desc:tr('Field inspection checklists with findings, corrections and photographic evidence.','Checklists de inspección con hallazgos, correcciones y evidencia fotográfica.'),count:walks.data.length,cls:'reports-walks'},{key:'observations',icon:'◉',title:tr('Safety Observations','Observaciones de Safety'),desc:tr('Individual hazard observations with priority, responsibility and evidence.','Observaciones individuales con prioridad, responsables y evidencia.'),count:obs.length,cls:'reports-observations'},{key:'corrections',icon:'✓',title:tr('Corrective Actions','Acciones Correctivas'),desc:tr('Documented corrections linked to the original safety observation.','Correcciones documentadas vinculadas a la observación original.'),count:corrections.data.length,cls:'reports-corrections'},{key:'discipline',icon:'⚠',title:tr('Disciplinary Actions','Acciones de Disciplina'),desc:tr('Employee disciplinary records and formal printable notices.','Registros disciplinarios y avisos formales imprimibles.'),count:disc.data.length,cls:'reports-discipline'}];const registered=docs.data||[],finalCount=registered.filter(d=>d.document_status==='final').length,reviewCount=registered.filter(d=>['submitted','under_review'].includes(d.document_status)).length;frame('<section class="observations-shell report-center"><div class="report-center-hero"><div><small>'+tr('G&E SAFETY DOCUMENT CONTROL','CONTROL DOCUMENTAL G&E SAFETY')+'</small><h1>'+tr('Report Center','Centro de Reportes')+'</h1><p>'+esc(project.name||'—')+' · '+tr('Select a category, choose a record and open its professional PDF-ready report.','Seleccione una categoría, elija un registro y abra su reporte profesional listo para PDF.')+'</p></div><div class="report-center-project"><span>'+tr('CURRENT PROJECT','PROYECTO ACTUAL')+'</span><strong>'+esc(project.name||'—')+'</strong><small>'+esc(project.general_contractor||'')+'</small></div></div><div class="document-control-strip"><div><strong>'+registered.length+'</strong><span>'+tr('Registered Documents','Documentos Registrados')+'</span></div><div><strong>'+finalCount+'</strong><span>'+tr('Final / Locked','Finales / Bloqueados')+'</span></div><div><strong>'+reviewCount+'</strong><span>'+tr('Under Review','En Revisión')+'</span></div><div><strong>v1+</strong><span>'+tr('Version Controlled','Control de Versiones')+'</span></div></div><div class="report-category-grid report-category-five">'+cats.map(x=>'<button class="report-category '+x.cls+'" data-category="'+x.key+'"><span class="report-category-icon">'+x.icon+'</span><div><h2>'+esc(x.title)+'</h2><p>'+esc(x.desc)+'</p></div><strong>'+x.count+'</strong><small>'+tr('OPEN CATEGORY','ABRIR CATEGORÍA')+' →</small></button>').join('')+'</div><section class="report-library card"><div class="report-library-head"><div><small>'+tr('REPORT LIBRARY','BIBLIOTECA DE REPORTES')+'</small><h2 id="report-library-title"></h2></div></div><div class="report-filter-bar"><input id="report-search" type="search" placeholder="'+tr('Search report, area, employee, category…','Buscar reporte, área, empleado, categoría…')+'"><select id="report-date-filter"><option value="all">'+tr('All dates','Todas las fechas')+'</option><option value="today">'+tr('Today','Hoy')+'</option><option value="week">'+tr('Last 7 days','Últimos 7 días')+'</option><option value="month">'+tr('Last 30 days','Últimos 30 días')+'</option></select></div><div id="report-library-list"></div></section></section>');const title=document.querySelector('#report-library-title'),list=document.querySelector('#report-library-list'),search=document.querySelector('#report-search'),dateFilter=document.querySelector('#report-date-filter');let currentCategory='daily';function empty(){return '<div class="report-empty">'+tr('No reports in this category yet.','Aún no hay reportes en esta categoría.')+'</div>'}function docMeta(type,source){const d=registered.find(x=>x.report_type===type&&x.source_id===source);return d?'<span class="document-id">'+esc(d.report_number)+' · v'+d.version+' · '+esc(d.document_status.toUpperCase())+'</span>':''}function row(kind,id,name,meta,status='',type=''){return '<button class="report-record" data-kind="'+kind+'" data-id="'+id+'"><div class="report-record-main"><strong>'+esc(name)+'</strong>'+docMeta(type,id)+'<span>'+esc(meta)+'</span></div>'+(status?'<span class="report-record-status">'+esc(status)+'</span>':'')+'<span class="report-open-pdf">PDF / '+tr('VIEW','VER')+' ›</span></button>'}function bind(){list.querySelectorAll('.report-record').forEach(el=>el.onclick=()=>{const k=el.dataset.kind,id=el.dataset.id;if(k==='daily')navigate('report');else if(k==='walk')navigate('safetyWalkReport',id);else if(k==='discipline')navigate('disciplineReport',id);else navigate('observationReport',id)})}function applyFilters(){const q=(search.value||'').toLowerCase(),range=dateFilter.value,now=Date.now();list.querySelectorAll('.report-record').forEach(el=>{const text=el.textContent.toLowerCase(),t=Number(el.dataset.time||0),days=t?(now-t)/86400000:0;const dateOk=range==='all'||(range==='today'&&t&&localDateKey(new Date(t).toISOString())===localDateKey())||(range==='week'&&t&&days<=7)||(range==='month'&&t&&days<=30);el.style.display=text.includes(q)&&dateOk?'':'none'})}function draw(key){currentCategory=key;document.querySelectorAll('.report-category').forEach(x=>x.classList.toggle('selected',x.dataset.category===key));const cat=cats.find(x=>x.key===key);title.textContent=cat?.title||'';if(key==='daily')list.innerHTML=todayObs.length?row('daily','today',tr("Today's Daily Safety Report",'Daily Safety Report de Hoy'),tr('Generated from today’s project activity','Generado desde la actividad del proyecto de hoy'),tr('PDF READY','LISTO PARA PDF')):empty();else if(key==='walks')list.innerHTML=walks.data.length?walks.data.map(x=>row('walk',x.id,tr('Daily Safety Walk Report','Reporte Daily Safety Walk'),fmt(x.created_at)+' · '+(x.creator?.name||'—'),x.overall_status.replaceAll('_',' '),'daily_safety_walk')).join(''):empty();else if(key==='discipline')list.innerHTML=disc.data.length?disc.data.map(x=>row('discipline',x.id,x.employee_name||tr('Employee Disciplinary Action','Acción Disciplinaria'),fmt(x.incident_date)+' · '+(x.issuer?.name||'—'),x.action_level.replaceAll('_',' '),'disciplinary_action')).join(''):empty();else if(key==='corrections')list.innerHTML=corrections.data.length?corrections.data.map(x=>row('observation',x.observation_id,x.observation?.area||tr('Corrective Action','Acción Correctiva'),fmt(x.created_at)+' · '+(x.author?.name||x.observation?.category||'—'),x.observation?.status?.replaceAll('_',' ')||'','correction')).join(''):empty();else list.innerHTML=obs.length?obs.map(x=>row('observation',x.id,x.area,fmt(x.created_at)+' · '+x.category,x.priority.toUpperCase(),'observation')).join(''):empty();bind();list.querySelectorAll('.report-record').forEach(el=>{const meta=el.querySelector('.report-record-main span:last-child')?.textContent||'';const m=meta.match(/\d{1,2}\/\d{1,2}\/\d{4}|\d{4}-\d{2}-\d{2}/);if(m){const d=new Date(m[0]);if(!isNaN(d))el.dataset.time=d.getTime()}});applyFilters()}search.oninput=applyFilters;dateFilter.onchange=applyFilters;document.querySelectorAll('.report-category').forEach(x=>x.onclick=()=>draw(x.dataset.category));draw('daily')}

async function observationReport(){const id=state.detail;const [oq,pq,aq]=await Promise.all([db.from('observations').select('*,creator:profiles!observations_created_by_fkey(name,email),assignee:profiles!observations_assigned_to_fkey(name,email),foreman:profiles!observations_foreman_id_fkey(name,email),jobsite_safety:profiles!observations_jobsite_safety_id_fkey(name,email)').eq('id',id).single(),db.from('observation_photos').select('*').eq('observation_id',id).order('created_at'),db.from('corrective_actions').select('*,author:profiles!corrective_actions_created_by_fkey(name)').eq('observation_id',id).order('created_at')]);if(oq.error)return error(oq.error);const o=oq.data,project=state.projects.find(p=>p.id===o.project_id)||{},photos=[];for(const p of pq.data||[]){const s=await db.storage.from('observation-photos').createSignedUrl(p.path,3600);if(s.data?.signedUrl)photos.push({...p,url:s.data.signedUrl})}const before=photos.filter(p=>p.kind==='before'),after=photos.filter(p=>p.kind==='after'),actions=aq.data||[],num='GES-OBS-'+String(o.id).slice(0,8).toUpperCase();frame(`<section class="print-report observation-print-report"><div class="print-report-watermark"><img src="/ge-logo.png"></div><header class="print-report-header"><img src="/ge-logo.png" alt="G&E"><div><small>G&E FLORIDA CONTRACTORS</small><h1>${tr('SAFETY OBSERVATION REPORT','REPORTE DE OBSERVACIÓN DE SAFETY')}</h1><p>G&E Safety Department</p></div><div class="print-report-number"><b>${num}</b><span>${esc(fmt(o.created_at))}</span></div></header><div class="print-report-meta"><div><span>${tr('PROJECT / JOBSITE','PROYECTO / JOBSITE')}</span><b>${esc(project.name||'—')}</b></div><div><span>${tr('GENERAL CONTRACTOR','CONTRATISTA GENERAL')}</span><b>${esc(project.general_contractor||'—')}</b></div><div><span>${tr('AREA / FLOOR','ÁREA / PISO')}</span><b>${esc(o.area||'—')}</b></div><div><span>${tr('CATEGORY','CATEGORÍA')}</span><b>${esc(o.category||'—')}</b></div><div><span>${tr('PRIORITY','PRIORIDAD')}</span><b class="report-priority ${esc(o.priority)}">${esc(o.priority.toUpperCase())}</b></div><div><span>${tr('STATUS','ESTADO')}</span><b>${esc(o.status.replaceAll('_',' ').toUpperCase())}</b></div></div><section class="print-report-block"><h2>${tr('OBSERVATION / HAZARD DESCRIPTION','OBSERVACIÓN / DESCRIPCIÓN DEL PELIGRO')}</h2><p>${esc(o.description)}</p></section><section class="print-report-people"><div><span>${tr('REPORTED BY','REPORTADO POR')}</span><b>${esc(o.creator?.name||o.creator?.email||'—')}</b></div><div><span>${tr('ASSIGNED PERSON','PERSONA ASIGNADA')}</span><b>${esc(o.assignee?.name||o.assignee?.email||'—')}</b></div><div><span>FOREMAN</span><b>${esc(o.foreman?.name||o.foreman?.email||'—')}</b></div><div><span>JOBSITE SAFETY</span><b>${esc(o.jobsite_safety?.name||o.jobsite_safety?.email||'—')}</b></div></section><section class="print-report-block"><h2>${tr('CORRECTIVE ACTION HISTORY','HISTORIAL DE ACCIONES CORRECTIVAS')}</h2>${actions.length?actions.map((a,i)=>`<div class="report-action-line"><b>#${i+1}</b><div><p>${esc(a.comment)}</p><small>${esc(a.author?.name||'—')} · ${esc(fmt(a.created_at))}</small></div></div>`).join(''):`<p>${tr('No corrective action documented yet.','Aún no hay acción correctiva documentada.')}</p>`}</section><section class="print-report-block"><h2>${tr('PHOTO EVIDENCE','EVIDENCIA FOTOGRÁFICA')}</h2><div class="report-photo-columns"><div><h3>${tr('BEFORE / HAZARD','ANTES / PELIGRO')}</h3><div class="report-photo-grid">${before.length?before.map(p=>`<figure><img src="${p.url}"><figcaption>${esc(fmt(p.created_at))}</figcaption></figure>`).join(''):`<p>—</p>`}</div></div><div><h3>${tr('AFTER / CORRECTION','DESPUÉS / CORRECCIÓN')}</h3><div class="report-photo-grid">${after.length?after.map(p=>`<figure><img src="${p.url}"><figcaption>${esc(fmt(p.created_at))}</figcaption></figure>`).join(''):`<p>—</p>`}</div></div></div></section><div class="print-report-closeout"><div><span>${tr('FINAL STATUS','ESTADO FINAL')}</span><strong>${esc(o.status.replaceAll('_',' ').toUpperCase())}</strong></div><div><span>${tr('CLOSED','CERRADO')}</span><strong>${o.closed_at?esc(fmt(o.closed_at)):tr('Pending','Pendiente')}</strong></div></div><footer class="print-report-footer"><span>G&E SAFETY DEPARTMENT</span><b>Safety Today · A Safer Tomorrow</b><span>${num}</span></footer><div class="no-print report-print-actions"><button onclick="window.print()">▤ ${tr('Download / Print PDF','Descargar / Imprimir PDF')}</button><button class="secondary" id="report-back">← ${tr('Back to Reports','Volver a Reportes')}</button></div></section>`);document.querySelector('#report-back').onclick=()=>navigate('reportCenter')}

async function report(){const now=new Date(),dayKey=localDateKey(now),rows=state.observations.filter(o=>o.project_id===state.project&&localDateKey(o.created_at)===dayKey),project=state.projects.find(p=>p.id===state.project)||{},dateText=new Intl.DateTimeFormat(state.lang==='es'?'es-US':'en-US',{weekday:'long',year:'numeric',month:'long',day:'numeric'}).format(now),timeText=new Intl.DateTimeFormat(state.lang==='es'?'es-US':'en-US',{hour:'numeric',minute:'2-digit',second:'2-digit',timeZoneName:'short'}).format(now),high=rows.filter(o=>o.priority==='high').length,medium=rows.filter(o=>o.priority==='medium').length,low=rows.filter(o=>o.priority==='low').length,open=rows.filter(o=>o.status==='open').length,pending=rows.filter(o=>o.status==='pending_verification').length,closed=rows.filter(o=>o.status==='closed').length;frame(`<div class="no-print report-actions"><button class="secondary" id="back">← ${tr('Back','Atrás')}</button><button id="print">▤ ${tr('Download / Print PDF','Descargar / Imprimir PDF')}</button></div><article class="report professional-report"><header class="report-header"><img src="/ge-logo.png" alt="G&E Florida Contractors"><div class="report-title"><span>G&E FLORIDA CONTRACTORS</span><h1>${tr('Daily Safety Report','Reporte diario de seguridad')}</h1><p>G&E Safety Department</p></div><div class="report-number"><small>${tr('REPORT DATE','FECHA DEL REPORTE')}</small><strong>${esc(dayKey)}</strong></div></header><section class="report-info"><div><small>${tr('PROJECT / JOBSITE','PROYECTO / JOBSITE')}</small><strong>${esc(project.name||'—')}</strong></div><div><small>${tr('GENERAL CONTRACTOR','CONTRATISTA GENERAL')}</small><strong>${esc(project.general_contractor||'—')}</strong></div><div><small>${tr('JOBSITE ADDRESS','DIRECCIÓN DEL JOBSITE')}</small><strong>${esc(project.address||'—')}</strong></div><div><small>${tr('PREPARED BY','PREPARADO POR')}</small><strong>${esc(state.profile.name||state.profile.email||'—')}</strong></div><div><small>${tr('DATE','FECHA')}</small><strong>${esc(dateText)}</strong></div><div><small>${tr('TIME','HORA')}</small><strong>${esc(timeText)}</strong></div></section><section class="report-summary"><div><strong>${rows.length}</strong><span>${tr('Total Observations','Observaciones totales')}</span></div><div><strong>${open}</strong><span>${tr('Open','Abiertas')}</span></div><div><strong>${pending}</strong><span>${tr('In Progress','En proceso')}</span></div><div><strong>${closed}</strong><span>${tr('Closed','Cerradas')}</span></div></section><section class="priority-summary"><span class="priority-high">${tr('High','Alta')}: <strong>${high}</strong></span><span class="priority-medium">${tr('Medium','Media')}: <strong>${medium}</strong></span><span class="priority-low">${tr('Low','Baja')}: <strong>${low}</strong></span></section><div id="report-rows" class="professional-report-rows"></div><footer class="report-footer"><div><strong>G&E Safety Department</strong><br><span>${tr('Safety Today. A Safer Tomorrow.','Seguridad hoy. Un mañana más seguro.')}</span></div><div>${tr('Generated','Generado')}: ${esc(dateText)} · ${esc(timeText)}</div></footer></article>`);document.querySelector('#back').onclick=back;document.querySelector('#print').onclick=()=>window.print();const box=document.querySelector('#report-rows');if(!rows.length){box.innerHTML=`<div class="report-empty">${tr('No safety observations were recorded for this project today.','No se registraron observaciones de seguridad para este proyecto hoy.')}</div>`;return}let i=0;for(const o of rows){i++;const [p,a]=await Promise.all([db.from('observation_photos').select('*').eq('observation_id',o.id),db.from('corrective_actions').select('*, author:profiles(name)').eq('observation_id',o.id).order('created_at')]);const signed=await Promise.all((p.data||[]).map(async x=>({...x,url:(await photoUrl(x.path)).data?.signedUrl})));const el=document.createElement('section');el.className='report-observation';el.innerHTML=`<div class="report-observation-head"><div><small>${tr('OBSERVATION','OBSERVACIÓN')} #${i}</small><h2>${esc(o.area)}</h2></div><div><span class="badge ${esc(o.priority)}">${esc(o.priority)}</span><span class="report-status">${esc(o.status.replaceAll('_',' '))}</span></div></div><div class="report-detail-grid"><p><small>${tr('CATEGORY','CATEGORÍA')}</small><strong>${esc(o.category)}</strong></p><p><small>${tr('REPORTED BY','REPORTADO POR')}</small><strong>${esc(o.creator?.name||'—')}</strong></p><p><small>${tr('ASSIGNED PERSON','PERSONA ASIGNADA')}</small><strong>${esc(o.assignee?.name||tr('Unassigned','Sin asignar'))}</strong></p><p><small>${tr('FOREMAN IN CHARGE','FOREMAN ENCARGADO')}</small><strong>${esc(o.foreman?.name||'—')}</strong></p><p><small>${tr('JOBSITE SAFETY','SAFETY DEL JOBSITE')}</small><strong>${esc(o.jobsite_safety?.name||'—')}</strong></p><p><small>${tr('DATE & TIME','FECHA Y HORA')}</small><strong>${esc(fmt(o.created_at))}</strong></p></div><div class="report-description"><small>${tr('OBSERVATION DETAILS','DETALLES DE LA OBSERVACIÓN')}</small><p>${esc(o.description)}</p></div>${signed.length?`<div class="report-photos">${signed.map(x=>`<figure><img src="${esc(x.url)}" alt="${esc(x.kind)}"><figcaption>${x.kind==='before'?tr('BEFORE / HAZARD','ANTES / PELIGRO'):tr('AFTER / CORRECTION','DESPUÉS / CORRECCIÓN')}</figcaption></figure>`).join('')}</div>`:''}${(a.data||[]).length?`<div class="report-corrections"><small>${tr('CORRECTIVE ACTION','ACCIÓN CORRECTIVA')}</small>${a.data.map(x=>`<p>${esc(x.comment)}<br><span>${esc(x.author?.name||'')} · ${esc(fmt(x.created_at))}</span></p>`).join('')}</div>`:''}`;box.append(el)}}
window.addEventListener('popstate',e=>{if(!state.session)return;const h=e.state;if(h?.geSafety){restoringHistory=true;state.page=h.page||'home';state.detail=h.detail||null;render();restoringHistory=false}else if(state.page!=='home'){navigate('home',null,{replace:true})}});
db?.auth.onAuthStateChange(event=>{if(event==='PASSWORD_RECOVERY')state.page='setPassword';setTimeout(()=>{if(state.session&&!history.state?.geSafety)history.replaceState({geSafety:true,page:state.page,detail:state.detail},'',location.href);refresh()},0)});refresh();
